  function announceStatus(){const h=$('#eq-layer-status');if(h)h.textContent=status(employment(),target());}
  function changedLayer(){const l=layer();if(l){l.status='À vérifier';announceStatus();save();editDraw();}}
  function wireCanvas(){
    const c=$('#eq-stage'),v=c?.parentElement;if(!c)return;
    const local=e=>{const r=c.getBoundingClientRect();return {x:(e.clientX-r.left)*64/r.width,y:(e.clientY-r.top)*64/r.height};};
    const showBrush=e=>{const b=$('#eq-brush');if(!b)return;b.hidden=viewMode.startsWith('Déplacer');const r=v.getBoundingClientRect(),size=brush*c.getBoundingClientRect().width/64;b.style.cssText=`left:${e.clientX-r.left+v.scrollLeft-size/2}px;top:${e.clientY-r.top+v.scrollTop-size/2}px;width:${size}px;height:${size}px`;};
    let start=null;
    c.addEventListener('pointerdown',e=>{if(e.button!==0)return;start={...local(e),clientX:e.clientX,clientY:e.clientY,left:v.scrollLeft,top:v.scrollTop,x0:layer()?.x||0,y0:layer()?.y||0};painting=true;c.setPointerCapture(e.pointerId);if(viewMode!=='Déplacer le calque'&&viewMode!=='Déplacer la vue')mark(e);});
    const mark=e=>{const l=layer();if(!l?.image)return;let p=local(e);if(viewMode.includes('corps'))l.mask.push({...p,size:brush,restore:viewMode.startsWith('Restaurer')});else{const a=-l.rotation*Math.PI/180,x=p.x-32-l.x,y=p.y-32-l.y;p={x:(x*Math.cos(a)-y*Math.sin(a))/l.scale+32,y:(x*Math.sin(a)+y*Math.cos(a))/l.scale+32};if(viewMode.includes('cette partie')){l.behind??=[];l.behind.push({...p,size:brush/l.scale,restore:viewMode.startsWith('Ramener')});}else l.erase.push({...p,size:brush/l.scale,restore:viewMode.startsWith('Restaurer')});}l.status='À vérifier';announceStatus();editDraw();};
    c.addEventListener('pointermove',e=>{showBrush(e);if(!painting||!start)return;if(viewMode==='Déplacer la vue'){v.scrollLeft=start.left-e.clientX+start.clientX;v.scrollTop=start.top-e.clientY+start.clientY;return;}const l=layer();if(!l?.image)return;if(viewMode==='Déplacer le calque'){const p=local(e);l.x=Math.round(Math.max(-64,Math.min(64,start.x0+p.x-start.x)));l.y=Math.round(Math.max(-64,Math.min(64,start.y0+p.y-start.y)));for(const k of ['x','y'])document.querySelectorAll(`[data-eq-setting="${k}"]`).forEach(n=>n.value=l[k]);l.status='À vérifier';announceStatus();editDraw();}else mark(e);});
    c.addEventListener('pointerup',()=>{painting=false;start=null;save();});c.addEventListener('pointercancel',()=>{painting=false;start=null;save();});c.addEventListener('pointerleave',()=>{$('#eq-brush').hidden=true;});
    v.addEventListener('wheel',e=>{e.preventDefault();setZoom(zoom+(e.deltaY<0?50:-50));},{passive:false});
  }
  function setZoom(n){zoom=Math.max(100,Math.min(1600,n));const c=$('#eq-stage');if(c){c.style.width=c.style.height=64*zoom/100+'px';$('#eq-zoom-label').textContent=zoom+' %';}}
